// Static scan of the decoded main image for the half-press position key,
// the ten-byte consumer address, and the v2 plane names. Reads only.
// Do not edit this file after it has run.
// Usage: node26 work/scripts/scan_keys_v1.mjs
import { readFileSync, writeFileSync, mkdirSync } from 'node:fs';
import { resolve } from 'node:path';

const image = readFileSync(resolve('inputs/00_0100_50000020.decoded.bin'));
const BASE = 0x60021020;

function findAll(pattern) {
  const out = [];
  let i = 0;
  while (i <= image.length - pattern.length) {
    const at = image.indexOf(pattern, i);
    if (at < 0) break;
    out.push(BASE + at);
    i = at + 1;
    if (out.length > 80) break;
  }
  return out;
}

const patterns = {
  mov88b2: Buffer.from([0xfc, 0xcc, 0xb2, 0x88, 0x00, 0x00]),
  mov5962: Buffer.from([0xfc, 0xcc, 0x62, 0x59, 0x00, 0x00]),
  mov84d1: Buffer.from([0xfc, 0xcc, 0xd1, 0x84, 0x00, 0x00]),
  mov99a1: Buffer.from([0xfc, 0xcc, 0xa1, 0x99, 0x00, 0x00]),
  addrConsumer: Buffer.from([0x84, 0xa3, 0x3c, 0xa3]),
};

const found = {};
for (const [name, pattern] of Object.entries(patterns)) {
  found[name] = findAll(pattern).map((a) => '0x' + a.toString(16));
}

const line = readFileSync(resolve('work/out/obs-k1-v2.jsonl'), 'utf8').split(/\n/).find((row) => row.includes('"id":"v2-rest"'));
const rest = JSON.parse(line);
const report = {
  imageBytes: image.length,
  found,
  planeNames: rest.planeNames,
  restMarks: rest.marks,
  restTarget: rest.target,
  restFrame: rest.actual.frame,
};
mkdirSync(resolve('work/out'), { recursive: true });
writeFileSync(resolve('work/out/scan-keys-v1.json'), JSON.stringify(report, null, 2) + '\n');
console.log(JSON.stringify({ counts: Object.fromEntries(Object.entries(found).map(([k, v]) => [k, v.length])), planeNames: rest.planeNames, mov88b2: found.mov88b2, addrConsumer: found.addrConsumer }, null, 2));
